// ─── VERBS ────────────────────────────────────────────────────────────────────
// vtype: 'modaal'|'onregelmatig'|'regelmatig'|'scheidbaar'|'reflexief'
// past: [singular ovt, plural ovt]   participle: voltooid deelwoord
// aux: 'hebben'|'zijn'   prefix: separable prefix (scheidbaar only)
// reflexive: true → reflexive pronouns added by getVerbForm

// ── Compact helpers ───────────────────────────────────────────────────────────
// r  = regelmatig   : r(inf, meaning, stem, pastSg, pastPl, participle, aux='hebben')
// ii = onregelmatig : ii(inf, meaning, [6 OTT forms], pastSg, pastPl, participle, aux='hebben')
// sp = scheidbaar   : sp(inf, meaning, prefix, stem, pastSg, pastPl, participle, aux='hebben')
// rf = reflexief    : rf(inf, meaning, stem, pastSg, pastPl, participle, aux='hebben')
const r = (inf,m,stem,ps,pp,part,aux='hebben') => {
  const t = stem.endsWith('t') ? stem : stem+'t';
  return {inf,meaning:m,vtype:'regelmatig',aux,past:[ps,pp],participle:part,
          forms:[stem,t,t,inf,inf,inf]};
};
const ii = (inf,m,f,ps,pp,part,aux='hebben') =>
  ({inf,meaning:m,vtype:'onregelmatig',aux,past:[ps,pp],participle:part,forms:f});
const sp = (inf,m,px,stem,ps,pp,part,aux='hebben') => {
  const t = stem.endsWith('t') ? stem : stem+'t';
  return {inf,meaning:m,vtype:'scheidbaar',prefix:px,aux,
          past:[ps+' '+px,pp+' '+px],participle:part,
          forms:[stem+' '+px,t+' '+px,t+' '+px,inf,inf,inf]};
};
const rf = (inf,m,stem,ps,pp,part,aux='hebben') => {
  const t = stem.endsWith('t') ? stem : stem+'t';
  return {inf,meaning:m,vtype:'reflexief',reflexive:true,aux,past:[ps,pp],participle:part,
          forms:[stem,t,t,inf,inf,inf]};
};

